// ============================================================
//  PASTE YOUR GOOGLE SHEET LINK BELOW (the whole browser URL)
// ============================================================
const SHEET_URL = 'PASTE_YOUR_GOOGLE_SHEET_URL_HERE';
// ------------------------------------------------------------

// Works out which trigger started this run (labeling or daily summary)
let job = 'label';
try { if ($('Daily Summary Trigger').first()) job = 'summary'; } catch (e) {}

if (!SHEET_URL.startsWith('https://docs.google.com/spreadsheets/')) {
  throw new Error('Sheet URL node: paste your Google Sheet link into SHEET_URL first.');
}
return [{ json: { url: SHEET_URL, job } }];

// Turns the Settings, Categories and Rules tabs into one config object.
// Also collects problems in the sheet (reported by Sync Report).
const norm = s => String(s ?? '').trim().toLowerCase();
const yes = v => ['true', 'yes', 'y', '1', 'x', '✓'].includes(norm(v));
// 'Dev / GitHub ' -> 'Dev/GitHub' (same form Gmail uses for nested labels)
const cleanPath = s => String(s ?? '').split('/').map(p => p.trim().replace(/\s+/g, ' ')).filter(Boolean).join('/');
const rows = name => $(name).all().map(i => i.json).filter(r => Object.keys(r).length > 0);
const problems = [];

// ---- Settings (key | value)
const S = {};
for (const r of rows('Read Settings')) if (r.key) S[norm(r.key)] = String(r.value ?? '').trim();
const alertEmail = S.alert_email || '';
const processedLabel = cleanPath(S.processed_label) || 'n8n-p';
const maxLabels = Number(S.max_labels) || 0;
const ignoreLabels = (S.ignore_labels || '').split(',').map(cleanPath).filter(Boolean);
const applyParents = yes(S.apply_parents);   // also add 'Dev' when adding 'Dev/GitHub'
if (!alertEmail) problems.push('Settings: alert_email is empty');

// ---- Categories (active | label | description | kind)
const RESERVED = ['inbox', 'spam', 'trash', 'unread', 'starred', 'important', 'sent', 'draft', 'chat'];
const categories = [], actions = [];
rows('Read Categories').forEach((r, i) => {
  const rowNo = i + 2;
  if (!yes(r.active)) return;
  const label = cleanPath(r.label);
  const kind = norm(r.kind || 'label');
  if (!label) { problems.push(`Categories row ${rowNo}: label is empty`); return; }
  if (kind === 'action') {
    if (!['starred', 'important'].includes(norm(label))) { problems.push(`Categories row ${rowNo}: action "${label}" not allowed (use STARRED or IMPORTANT)`); return; }
    actions.push({ label: label.toUpperCase(), description: String(r.description ?? '') });
    return;
  }
  if (RESERVED.includes(norm(label))) { problems.push(`Categories row ${rowNo}: "${label}" is a built-in Gmail name; set kind = action or rename`); return; }
  if (!String(r.description ?? '').trim()) problems.push(`Categories row ${rowNo}: "${label}" has no description (AI accuracy will suffer)`);
  categories.push({ label, description: String(r.description ?? '') });
});

// ---- Rules (active | field | contains | labels | skip_ai | note)
const rules = [];
rows('Read Rules').forEach((r, i) => {
  const rowNo = i + 2;
  if (!yes(r.active)) return;
  const field = norm(r.field || 'from');
  const contains = String(r.contains ?? '').trim();
  const labels = String(r.labels ?? '').split(',').map(cleanPath).filter(Boolean)
    .map(l => (['starred', 'important'].includes(norm(l)) ? l.toUpperCase() : l));
  if (!['from', 'subject', 'any'].includes(field)) { problems.push(`Rules row ${rowNo}: field must be from, subject or any (got "${r.field}")`); return; }
  if (!contains) { problems.push(`Rules row ${rowNo}: "contains" is empty`); return; }
  if (labels.length === 0) { problems.push(`Rules row ${rowNo}: "labels" is empty`); return; }
  const bad = labels.filter(l => RESERVED.includes(norm(l)) && !['starred', 'important'].includes(norm(l)));
  if (bad.length) { problems.push(`Rules row ${rowNo}: not allowed: ${bad.join(', ')}`); return; }
  rules.push({ field, contains, labels, skipAi: r.skip_ai === undefined || String(r.skip_ai).trim() === '' ? true : yes(r.skip_ai) });
});

return [{ json: { alertEmail, processedLabel, maxLabels, ignoreLabels, applyParents, categories, actions, rules, problems } }];

// Lists labels that must exist in Gmail (categories + rule labels + hidden marker).
// Parents of nested labels (e.g. "Dev" for "Dev/GitHub") are created first.
const cfg = $('Build Config').first().json;
const norm = s => String(s || '').trim().toLowerCase();
const have = new Set($input.all().map(i => norm(i.json.name)));
const SYSTEM = ['starred', 'important'];

const wanted = new Set();
cfg.categories.forEach(c => wanted.add(c.label));
cfg.rules.forEach(r => r.labels.forEach(l => { if (!SYSTEM.includes(norm(l))) wanted.add(l); }));

const withParents = new Map();
for (const name of wanted) {
  const parts = name.split('/').map(s => s.trim()).filter(Boolean);
  for (let i = 1; i <= parts.length; i++) {
    const n = parts.slice(0, i).join('/');
    if (!withParents.has(norm(n))) withParents.set(norm(n), n);
  }
}
const toCreate = [...withParents.values()]
  .filter(n => !have.has(norm(n)))
  .sort((a, b) => a.split('/').length - b.split('/').length)
  .map(name => ({ json: { action: 'create', name, hidden: false } }));

if (cfg.processedLabel && !have.has(norm(cfg.processedLabel)))
  toCreate.push({ json: { action: 'create', name: cfg.processedLabel, hidden: true } });

return toCreate.length ? toCreate : [{ json: { action: 'skip' } }];

// After sync: instant alert email for sync/config problems + rows for the Errors tab.
// Outputs: items with alertTo  -> Send Alert (Email)
//          items with stage    -> Append Errors
const cfg = $('Build Config').first().json;
const norm = s => String(s || '').trim().toLowerCase();
const labels = $input.all().map(i => i.json);
const have = new Set(labels.map(l => norm(l.name)));
const now = new Date().toISOString();

const planned = $('Plan Label Sync').all().map(i => i.json).filter(j => j.action === 'create');
const created = planned.filter(j => !j.hidden && have.has(norm(j.name))).map(j => j.name);
const failed = planned.filter(j => !have.has(norm(j.name))).map(j => j.name);

const known = new Set();
cfg.categories.forEach(c => known.add(norm(c.label)));
cfg.rules.forEach(r => r.labels.forEach(l => known.add(norm(l))));
cfg.ignoreLabels.forEach(l => known.add(norm(l)));
known.add(norm(cfg.processedLabel));
const knownList = [...known];
const unknown = labels.filter(l => l.type === 'user').map(l => String(l.name)).filter(n => {
  const k = norm(n);
  if (known.has(k)) return false;
  if (knownList.some(p => k.startsWith(p + '/') || p.startsWith(k + '/'))) return false;
  return true;
}).sort();

const store = $getWorkflowStaticData('global');
const DAY = 24 * 60 * 60 * 1000;
const problemKey = failed.concat(cfg.problems).map(norm).sort().join('|');
const unknownKey = unknown.map(norm).join('|');
const problemsDue = problemKey && (problemKey !== store.problemKey || Date.now() - (store.problemAt || 0) > DAY);
const unknownChanged = unknown.length > 0 && unknownKey !== (store.unknownKey ?? '');
store.unknownKey = unknownKey;
if (!problemKey) store.problemKey = '';
if (!(created.length || problemsDue || unknownChanged)) return [];
if (problemsDue) { store.problemKey = problemKey; store.problemAt = Date.now(); }

const out = [];
const parts = [];
if (created.length) parts.push('✅ Created in Gmail:\n' + created.map(n => '  - ' + n).join('\n'));
if (failed.length) parts.push('❌ Could NOT be created in Gmail:\n' + failed.map(n => '  - ' + n).join('\n'));
if (cfg.problems.length) parts.push('⚠️ Problems in your Google Sheet:\n' + cfg.problems.map(p => '  - ' + p).join('\n'));
if (unknown.length) parts.push('ℹ️ Gmail labels not used by any category or rule:\n' + unknown.map(n => '  - ' + n).join('\n') +
  '\n  Add them to Categories/Rules, or to ignore_labels in Settings.');

const bits = [];
if (created.length) bits.push(`${created.length} created`);
if (failed.length) bits.push(`${failed.length} failed`);
if (cfg.problems.length) bits.push(`${cfg.problems.length} sheet problem(s)`);
if (unknown.length) bits.push(`${unknown.length} unused label(s)`);
if (cfg.alertEmail) out.push({ json: { alertTo: cfg.alertEmail, alertSubject: `[n8n labeler] Label sync: ${bits.join(', ')}`, alertText: parts.join('\n\n') } });

if (problemsDue) {
  failed.forEach(n => out.push({ json: { timestamp: now, stage: 'label_create_failed', message_id: '', from: '', subject: '', error: `Could not create Gmail label "${n}"` } }));
  cfg.problems.forEach(p => out.push({ json: { timestamp: now, stage: 'config', message_id: '', from: '', subject: '', error: p } }));
}
return out;

// Applies sheet Rules to every email. Emails fully handled by rules skip the AI.
const cfg = $('Build Config').first().json;
const norm = s => String(s || '').trim().toLowerCase();
const idByName = {};
for (const l of $('Get Labels After Sync').all()) idByName[norm(l.json.name)] = l.json.id;
const idOf = n => (['starred', 'important'].includes(norm(n)) ? n.toUpperCase() : idByName[norm(n)]);
const parentsOf = n => { const p = String(n).split('/'); const out = []; for (let i = 1; i < p.length; i++) out.push(p.slice(0, i).join('/')); return out; };
const processedId = idByName[norm(cfg.processedLabel)] || null;

return $('Emails').all().map(e => {
  const m = e.json;
  const from = m.from?.text || '';
  const subject = m.subject || '';
  const body = String(m.text || m.snippet || '').slice(0, 800);
  const matched = cfg.rules.filter(r => {
    const hay = r.field === 'from' ? from : r.field === 'subject' ? subject : `${from} ${subject}`;
    return norm(hay).includes(norm(r.contains));
  });
  const ruleLabels = [], ruleIds = [];
  for (const r of matched) for (const l of r.labels) {
    const id = idOf(l);
    if (id && !ruleIds.includes(id)) { ruleIds.push(id); ruleLabels.push(l); }
    if (id && cfg.applyParents) for (const p of parentsOf(l)) { const pid = idByName[norm(p)]; if (pid && !ruleIds.includes(pid)) ruleIds.push(pid); }
  }
  const needsAI = matched.length === 0 || matched.some(r => !r.skipAi);
  return { json: { messageId: m.id, from, subject, body, ruleLabels, ruleIds, processedId, needsAI } };
});

// Emails fully labeled by rules (no AI call).
return $input.all().filter(i => !i.json.needsAI).map(i => {
  const s = i.json;
  const ids = s.processedId ? s.ruleIds.concat([s.processedId]) : s.ruleIds;
  return { json: { messageId: s.messageId, from: s.from, subject: s.subject,
                   labels: s.ruleLabels, labelIds: ids, source: 'rule', aiAnswer: '' } };
});

// One AI prompt per email that still needs the AI.
const cfg = $('Build Config').first().json;
const norm = s => String(s || '').trim().toLowerCase();
const idByName = {};
for (const l of $('Get Labels After Sync').all()) idByName[norm(l.json.name)] = l.json.id;

const allowed = {}, catLines = [], actLines = [];
for (const c of cfg.categories) {
  const id = idByName[norm(c.label)];
  if (!id) continue;
  const parents = [];
  if (cfg.applyParents) { const p = c.label.split('/'); for (let k = 1; k < p.length; k++) { const pid = idByName[norm(p.slice(0, k).join('/'))]; if (pid) parents.push(pid); } }
  allowed[norm(c.label)] = { label: c.label, id, parents };
  catLines.push(`- ${c.label}: ${c.description}`);
}
for (const a of cfg.actions) {
  allowed[norm(a.label)] = { label: a.label, id: a.label };
  actLines.push(`- ${a.label}: ${a.description}`);
}
if (Object.keys(allowed).length === 0) return [];
// If the AI answers just 'GitHub' for 'Dev/GitHub', accept it when that short name is unique
const leafCount = {};
for (const k of Object.keys(allowed)) { const leaf = k.split('/').pop(); leafCount[leaf] = (leafCount[leaf] || 0) + 1; }
for (const [k, v] of Object.entries({ ...allowed })) { const leaf = k.split('/').pop(); if (k.includes('/') && leafCount[leaf] === 1 && !allowed[leaf]) allowed[leaf] = v; }
const limit = cfg.maxLabels > 0 ? `Use at most ${cfg.maxLabels} names.` : '';

return $input.all().filter(i => i.json.needsAI).map(i => {
  const s = i.json;
  const already = s.ruleLabels.length ? `\nAlready applied by rules (don't repeat): ${s.ruleLabels.join(', ')}\n` : '';
  const prompt =
`You organise emails in Gmail.

TOPIC LABELS (pick every one that clearly applies, or none). Names with "/" are sub-labels: use the full name, e.g. "Dev/GitHub":
${catLines.join('\n') || '(none)'}

ACTIONS (add only if clearly true):
${actLines.join('\n') || '(none)'}
${already}
Email:
From: ${s.from}
Subject: ${s.subject}
Body:
${s.body}

Answer with ONLY a JSON array of names exactly as written above, e.g. ["IELTS","STARRED"].
Return [] if nothing clearly applies. ${limit} No explanation.`;
  return { json: { messageId: s.messageId, from: s.from, subject: s.subject, prompt, allowed,
                   ruleLabels: s.ruleLabels, ruleIds: s.ruleIds, processedId: s.processedId, maxLabels: cfg.maxLabels } };
});

// Reads the AI answer and produces:
//   apply items (messageId + labelIds)           -> Add Labels
//   error rows  (timestamp, stage, ... , error)  -> Errors tab
const src = $('Build AI Input').all();
const norm = s => String(s || '').trim().toLowerCase();
const now = new Date().toISOString();
const out = [];

$input.all().forEach((item, i) => {
  const s = src[i].json;
  const errRow = (stage, error) => ({ json: { timestamp: now, stage, message_id: s.messageId, from: s.from, subject: s.subject, error } });

  // AI call failed (e.g. Groq rate limit): apply rule labels only, DON'T mark processed -> retried next run
  if (item.json.error) {
    out.push(errRow('ai_error', String(item.json.error).slice(0, 300)));
    if (s.ruleIds.length) out.push({ json: { messageId: s.messageId, from: s.from, subject: s.subject,
      labels: s.ruleLabels, labelIds: s.ruleIds, source: 'rule', aiAnswer: '(AI failed)' } });
    return;
  }

  const raw = String(item.json.text ?? '').trim();
  let names = [];
  const m = raw.match(/\[[\s\S]*?\]/);
  try { names = m ? JSON.parse(m[0]) : []; } catch (e) { names = []; }
  if (!Array.isArray(names) || (!m && raw)) names = raw.split(/[,\n]/);
  names = names.map(n => String(n).replace(/^[\s"'`*\-\[]+|[\s"'`*.\]]+$/g, '')).filter(Boolean);

  const aiIds = [], aiLabels = [], unknown = [], aiParents = [];
  for (const n of names) {
    if (['other', 'none'].includes(norm(n))) continue;
    const hit = s.allowed[norm(n)];
    if (!hit) { unknown.push(n); continue; }
    if (!aiIds.includes(hit.id) && !s.ruleIds.includes(hit.id)) { aiIds.push(hit.id); aiLabels.push(hit.label); aiParents.push(hit.parents || []); }
  }
  const capIds = s.maxLabels > 0 ? aiIds.slice(0, s.maxLabels) : aiIds;
  const capLabels = s.maxLabels > 0 ? aiLabels.slice(0, s.maxLabels) : aiLabels;
  const parentIds = (s.maxLabels > 0 ? aiParents.slice(0, s.maxLabels) : aiParents).flat();
  const ids = [...new Set(s.ruleIds.concat(capIds).concat(parentIds).concat(s.processedId ? [s.processedId] : []))];

  out.push({ json: { messageId: s.messageId, from: s.from, subject: s.subject,
    labels: s.ruleLabels.concat(capLabels), labelIds: ids,
    source: s.ruleIds.length ? 'rule+ai' : 'ai', aiAnswer: raw.slice(0, 200) } });
  if (unknown.length) out.push(errRow('unknown_label', `AI returned unknown name(s): ${unknown.join(', ')} | answer: ${raw.slice(0, 200)}`));
});
return out;

// One row for the Log tab (label added successfully).
const s = $('Route').item.json;
return { json: {
  timestamp: new Date().toISOString(),
  message_id: s.messageId,
  from: s.from,
  subject: s.subject,
  labels: (s.labels || []).join(', ') || '(none)',
  source: s.source,
  ai_answer: s.aiAnswer || ''
} };

// One row for the Errors tab (Gmail refused to add the labels).
const s = $('Route').item.json;
const err = $json.error;
return { json: {
  timestamp: new Date().toISOString(),
  stage: 'add_labels',
  message_id: s.messageId,
  from: s.from,
  subject: s.subject,
  error: String(err?.message || err || 'Unknown error').slice(0, 300)
} };

// Daily summary of the last 24 hours from the Log and Errors tabs.
const S = {};
for (const r of $('Read Settings').all().map(i => i.json)) if (r.key) S[String(r.key).trim().toLowerCase()] = String(r.value ?? '').trim();
const since = Date.now() - 24 * 60 * 60 * 1000;
const recent = name => $(name).all().map(i => i.json).filter(r => r.timestamp && Date.parse(r.timestamp) >= since);
const logs = recent('Read Log');
const errors = recent('Read Errors');

const byLabel = {}, bySource = {};
for (const r of logs) {
  bySource[r.source || '?'] = (bySource[r.source || '?'] || 0) + 1;
  for (const l of String(r.labels || '').split(',').map(s => s.trim()).filter(Boolean)) byLabel[l] = (byLabel[l] || 0) + 1;
}
const byStage = {};
for (const e of errors) byStage[e.stage || '?'] = (byStage[e.stage || '?'] || 0) + 1;
const fmt = o => Object.entries(o).sort((a, b) => b[1] - a[1]).map(([k, v]) => `  - ${k}: ${v}`).join('\n') || '  (none)';

const text =
`Gmail labeler — last 24 hours

Emails labeled: ${logs.length}
By source (rule = no AI used):
${fmt(bySource)}

By label:
${fmt(byLabel)}

Errors: ${errors.length}
${fmt(byStage)}
${errors.length ? '\nLatest errors:\n' + errors.slice(-10).map(e => `  - [${e.stage}] ${e.subject || ''} → ${e.error}`).join('\n') : ''}

Full details: ${$('Sheet URL').first().json.url}`;

return [{ json: { alertTo: S.alert_email, alertSubject: `[n8n labeler] Daily summary: ${logs.length} labeled, ${errors.length} errors`, alertText: text } }];
